---@field controller                    	Engine.Modules.LuaBehaviour             
---@field RewardAinRoot                 	UnityEngine.RectTransform               	@ 0    
---@field BtnTips                       	UnityEngine.RectTransform               	@ 1    
---@field BtnGetOne                     	UnityEngine.RectTransform               	@ 2    
---@field OneCommonBtnConsumePop        	UnityEngine.RectTransform               	@ 3    
---@field BtnGetTen                     	UnityEngine.RectTransform               	@ 4    
---@field CommonBtnConsumePop           	UnityEngine.RectTransform               	@ 5    
---@field BtnJump                       	UnityEngine.RectTransform               	@ 6    
---@field ImgOpen                       	UnityEngine.RectTransform               	@ 7    
---@field RewardLoopView                	SuperScrollView.LoopListView2           	@ 8    
local RegressionNewRewardDialog = Class('RegressionNewRewardDialog')
local AniRootPath = "Game.Activity.RegressionActivity.RegressionNewRewardAniRoot"
local CellPath = "Game.Activity.RegressionActivity.Cell.RegressionNewRewardCell"
local cs_coroutine = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders
---@type RegressionUtils
local RegressionUtils = import('Game.Activity.RegressionActivity.RegressionUtils')

local JumpType = {
	One = 1,
	Five = 2,
}

local JumpNum = {
	[JumpType.One] = 1,
	[JumpType.Five] = 5,
}

function RegressionNewRewardDialog:__init()
	self.co = nil
end

function RegressionNewRewardDialog:__delete()
	self:RemoveCo()
end

function RegressionNewRewardDialog:Awake()
	self:InitEnv()
	self:AddUIClick()
	self:AddEventListener()
end

function RegressionNewRewardDialog:RemoveEventListener()
	Events.RemoveListener(Constants.EventNames.EveryThingChangeEventName, self.goodsChangeEvent)
end

function RegressionNewRewardDialog:AddEventListener()
	self.goodsChangeEvent = Events.AddListener(Constants.EventNames.EveryThingChangeEventName,Bind(self,self.UpdateRedPoint))
end

function RegressionNewRewardDialog:AddUIClick()
	SetButtonAction(self.BtnGetOne,Bind(self,self.OnBtnOneClick))
	SetButtonAction(self.BtnGetTen,Bind(self,self.OnBtnTenClick))
	SetButtonAction(self.BtnJump,Bind(self,self.OnBtnJumpAniClick))
	SetButtonAction(self.BtnTips,Bind(self,self.OnBtnTipsClick))
end

function RegressionNewRewardDialog:InitEnv()
	local env = CfUtils.GetLuaScr(self.RewardAinRoot,AniRootPath)
	if isNotNull(env) then
		---@type RegressionNewRewardAniRoot
		self.rewardAniEnv = env
	end
end

function RegressionNewRewardDialog:Refresh(config)
	self.config = config
	self.dojo = RegressionUtils.GetRegressHomeDojo()
	self.data = self.dojo:GetJackPotInfo()
	self:SetIsJumpAni()
	self:InitCirclesVos()
	self:RefreshListShow()
	self:RefreshGridShow()
	self:RefreshCurrencyShow()
end

function RegressionNewRewardDialog:RefreshTopGoods()
	CfUtils.RefreshTopGoods({self.data.costId, Constants.Currency.FreeDiamondId})
end

function RegressionNewRewardDialog:RefreshCurrencyShow()
	UICommonUtils.FillCommonBtnConsumePop(self.OneCommonBtnConsumePop, self.data.costId, self.data.costNum)
	UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, self.data.costId, self.data.costNum * JumpNum[JumpType.Five])

end

function RegressionNewRewardDialog:RefreshListShow()
	self:RefreshRewardListShow()
end

function RegressionNewRewardDialog:RefreshRewardListShow()
	local count = #self.circleVos
	local listInitParam = CS.SuperScrollView.LoopListViewInitParam.CopyDefaultInitParam()
	local listItemData  = self.RewardLoopView:GetItemPrefabConfData("Cell")
	local itemSizeDelta = listItemData.mItemPrefab.transform.sizeDelta
	local listItemSize  = self.RewardLoopView.IsVertList and itemSizeDelta.y or itemSizeDelta.x
	listInitParam.mItemDefaultWithPaddingSize = listItemSize + listItemData.mPadding
	
	
	if not self.RewardLoopView.IsListViewInit then
		self.RewardLoopView:InitListView(count, Bind(self, self.OnGetItemByIndex), listInitParam)
	else
		GameUtils.ReloadData(self.RewardLoopView, count)
	end
	
	local preWidth = self.RewardLoopView.ContainerTrans.rect.width
	self.RewardLoopView.mOnDragingAction = function()
		local  currentWidth  = self.RewardLoopView.ContainerTrans.rect.width
		if currentWidth == preWidth then
			return
		end
		preWidth = currentWidth
		self:SetSliderPercentByWidth(currentWidth)
	end
	
	local index = self:GetMoveCellIndex()
	self.RewardLoopView:MovePanelToItemIndex(index - 1)
	
	self:RemoveCo()
	self.co = cs_coroutine.start(function ()
		while not self.RewardLoopView.IsListViewInitComplete do
			cs_coroutine.yield_return(Yielders.EndOfFrame)
		end
		self:SetSliderPercentByWidth(self.RewardLoopView.ContainerTrans.rect.width)
	end)
end

function RegressionNewRewardDialog:RemoveCo()
	if self.co  then
		cs_coroutine.stop(self.co)
		self.co = nil
	end
end

function RegressionNewRewardDialog:SetSliderPercentByWidth()
	local totalDay = self:GetTotalCircle()
	local cellWidth = 160
	local cellWidthAndDis = 160
	local count = 0
	local permanentProgressData = self.circleVos
	for i  = 1 , #permanentProgressData do
		local oneData = permanentProgressData[i]
		if i == 1 then
			if totalDay >= checkInt(oneData.rounds)  then
				count = count +  cellWidth/2
			else
				count = count +   totalDay/ oneData.rounds * cellWidth/2
				break
			end
		else
			if totalDay >= checkInt(oneData.rounds)  then
				count = count +  cellWidthAndDis
			else
				local lastData = permanentProgressData[i -1]
				count = count  + (totalDay - lastData.rounds ) * cellWidthAndDis/(oneData.rounds - lastData.rounds )
				break
			end
		end
	end
	self.Slider.value = count / (self.RewardLoopView.ContainerTrans.rect.width + self.Slider.transform.sizeDelta.x)
end

function RegressionNewRewardDialog:GetTotalCircle()
	return self.data.nowRound - 1
end

function RegressionNewRewardDialog:GetHasGetId()
	return checkNumber(self.data.receiveRoundId)
end

function RegressionNewRewardDialog:GetMoveCellIndex()
	local index = 1
	local hasGetId = self:GetHasGetId()
	local curCircle = self:GetTotalCircle()
	local isFind = false
	for i, v in pairs(self.circleVos) do
		if curCircle >= v.rounds then
			index = i
		end
		
		if checkNumber(v.id) > hasGetId and curCircle >= v.rounds then
			index = i
			isFind = true
			break
		end
	end
	return index
end

function RegressionNewRewardDialog:OnGetItemByIndex(listView, index)
	if index < 0 or index >= #self.circleVos then
		return
	end
	
	local index = index + 1
	local data = self.circleVos[index]
	local cell = listView:NewListViewItem("Cell")
	if not isNull(cell) then
		local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
		if not isNull(tableCellEnv) then
			tableCellEnv:InitCellData(Bind(self,self.OnGetRewardClick), data, self.totalCount)
			local curCircle = self:GetTotalCircle()
			local isGet = self:JudgeIsGet(data)
			tableCellEnv:RefreshShow(curCircle, isGet)
		end
	end
	return cell
end

function RegressionNewRewardDialog:JudgeIsGet(data)
	local curGetId = self:GetHasGetId()
	return curGetId >= checkNumber(data.id)
end

function RegressionNewRewardDialog:OnGetRewardClick()
	GameUtils.Request(Interfaces.NewRegressDrawCircleReward, nil,function(request, response)
		if checkNumber(response.errCode) == 0 then
			local responseData = response.data
			self:UpdateHasGetId()
			GameUtils.ReloadData(self.RewardLoopView, table.count(self.circleVos))
			if table.count(responseData.rewards) > 0 then
				GoodsUtils.DrawRewards(responseData.rewards,true)
				CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
			end
			self:RefreshCurrencyShow()
			RegressionUtils.RefreshRedPoint(self.config.type)
		end
	end)
end

function RegressionNewRewardDialog:UpdateHasGetId()
	local totalCircle = self:GetTotalCircle()
	local receiveId = self:GetHasGetId()
	for i, v in pairs(self.circleVos) do
		if totalCircle >= v.rounds and checkNumber(v.id) >= checkNumber(receiveId)  then
			self.data.receiveRoundId = v.id
		end
	end
end

function RegressionNewRewardDialog:RefreshGridShow()
	self.rewardAniEnv:RefreshGridShow(self.data, self.dojo.groupId)
end

function RegressionNewRewardDialog:IsJumpAni()
	local key = self:GetJumpAniKey()
	local isJump = CfUtils.GetLocalData(key,0)
	return checkNumber(isJump) == 1
end

function RegressionNewRewardDialog:OnBtnJumpAniClick()
	local isJump = self:IsJumpAni()
	local key = self:GetJumpAniKey()
	CfUtils.WriteLocalData(key,isJump and 0 or 1)
	self:SetIsJumpAni()
end

function RegressionNewRewardDialog:SetIsJumpAni()
	local isJump = self:IsJumpAni()
	CfUtils.SetActive(self.ImgOpen, isJump)
end

function RegressionNewRewardDialog:GetJumpAniKey()
	return table.concat({"RegressionNewRewardDialog",self.dojo.groupId})
end


function RegressionNewRewardDialog:OnBtnOneClick()
	local isEnough = self:IsItemEnough(JumpType.One)
	if not isEnough then
		return
	end
	local num = JumpNum[JumpType.One]
	GameUtils.Request(Interfaces.NewRegressHurl,{num = num},function(request, response)
		if checkNumber(response.errCode) == 0 then
			local responseData = response.data
			local points = responseData.points
			local buffPoints = responseData.buffPoints
			local isJumpAni = self:IsJumpAni()
			if isJumpAni then
				self:RefreshShowInfo(responseData, true, num)
			else
				self.rewardAniEnv:StartJump(JumpType.One, points, buffPoints, function()
					self:RefreshShowInfo(responseData,false, num)
				end)
			end
		end
	end)
end

function RegressionNewRewardDialog:RefreshShowInfo(responseData ,needGoTo ,num)
	self.dojo:UpdateJackPotInfo(responseData.jackpotInfo)
	if needGoTo then
		self.rewardAniEnv:GoToPos(responseData.jackpotInfo.nowStep)
	end
	GameUtils.ReloadData(self.RewardLoopView, table.count(self.circleVos))
	self:SetSliderPercentByWidth()
	GoodsUtils.DrawRewards({ { goodsId = self.data.costId, num = -num } }, false)
	if table.count(responseData.rewards) > 0 then
		GoodsUtils.DrawRewards(responseData.rewards,true)
		CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards , forceIgnoreSort = true } })
	end
	self:RefreshCurrencyShow()
	RegressionUtils.RefreshRedPoint(self.config.type)
end

function RegressionNewRewardDialog:OnBtnTenClick()
	local isEnough = self:IsItemEnough(JumpType.Five)
	if not isEnough then
		return
	end
	local num = JumpNum[JumpType.Five]
	GameUtils.Request(Interfaces.NewRegressHurl,{num = num},function(request, response)
		if checkNumber(response.errCode) == 0 then
			local responseData = response.data
			local points = responseData.points
			local buffPoints = responseData.buffPoints
			local isJumpAni = self:IsJumpAni()
			if isJumpAni then
				self:RefreshShowInfo(responseData, true, num)
			else
				self.rewardAniEnv:StartJump(JumpType.Five, points, buffPoints, function()
					self:RefreshShowInfo(responseData,false, num)
				end)
			end
		end
	end)
end

function RegressionNewRewardDialog:OnBtnTipsClick()
	if checkNumber(self.data.ruleId) > 0 then
		CfUtils.ShowModuleToast(self.data.ruleId)
	end
end

function RegressionNewRewardDialog:UpdateRedPoint()
	RegressionUtils.RefreshRedPoint(self.config.type)
end

function RegressionNewRewardDialog:IsItemEnough(jumpType)
	local num = jumpType == JumpType.One and self.data.costNum or self.data.costNum * JumpNum[JumpType.Five]
	return GoodsUtils.GetThingNo(self.data.costId) >= num
end

function RegressionNewRewardDialog:InitCirclesVos()
	self.circleVos = self.data.roundRewardsInfo
	self.totalCount = #self.circleVos
end

function RegressionNewRewardDialog:OnDestroy()
	self:RemoveEventListener()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return RegressionNewRewardDialog